<script setup lang="ts">
import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { api,query,money,isCancelled,contextVersion } from '../lib/api'
import { isParent,isAdmin,selectedDate,campuses,currentCampusId } from '../lib/state'
import { useResource,notify } from '../lib/ui'
import type { Student,Account,Attachment } from '../lib/types'
import { attachmentUrl } from '../mobile/endpoints'
import { serviceBase } from '../mobile/platform'
import PageHeader from '../components/PageHeader.vue'
import SoftSelect from '../components/SoftSelect.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
import StudentAvatar from '../components/StudentAvatar.vue'
import AttachmentList from '../components/AttachmentList.vue'
interface Intent {id:number;studentId:number;studentName:string;courseName:string;parentName:string;campusName:string;intention:string;updatedAt:string}
interface Meal {id:number;studentId:number;studentName:string;className:string;campusName:string;parentName:string;ordered:boolean;amount:number;version:number;date:string}
interface Config {campusId:number;campusName:string;mealPrice:number|null;paymentQr:Attachment|null;version:number}
interface Family {student:Student;date:string;accounts:(Account&{intention:string|null;intentVersion:number;lowBalance:boolean})[];settings:Config;meal:Meal|null}
const screenAbort=new AbortController()
onBeforeUnmount(()=>screenAbort.abort())
const route=useRoute(),studentId=ref<string|number>(String(route.query.studentId||'')),busy=ref(false),actionError=ref('')
const resource=useResource(async()=>{
  const students=await api<Student[]>('/students'),id=Number(studentId.value)||(isParent.value?students[0]?.id:undefined)
  const [family,intents,meals]=await Promise.all([id?api<Family>('/family-services'+query({studentId:id})):null,isParent.value?[]:api<Intent[]>('/renewal-intents'+query({studentId:studentId.value})),isParent.value?[]:api<Meal[]>('/meal-orders'+query({date:selectedDate.value,studentId:studentId.value}))])
  return {students,family,intents,meals}
},[studentId,selectedDate])
const family=computed(()=>resource.data.value?.family),low=computed(()=>family.value?.accounts.filter(a=>a.lowBalance)||[])
const configCampusId=ref<string|number>(''),configPrice=ref(''),configQr=ref<Attachment|null>(null)
const configCampuses=computed(()=>campuses.value.filter(c=>currentCampusId.value===null||c.id===currentCampusId.value))
const config=useResource(()=>isAdmin.value&&configCampusId.value?api<Config>(`/campuses/${configCampusId.value}/family-services`):Promise.resolve(null),[configCampusId])
watch(config.data,value=>{configPrice.value=value?.mealPrice==null?'':String(value.mealPrice/100);configQr.value=value?.paymentQr||null})
watch(contextVersion,()=>{studentId.value='';configCampusId.value='';busy.value=false;actionError.value='';configPrice.value='';configQr.value=null},{flush:'sync'})
async function act(action:()=>Promise<unknown>,success:string){if(busy.value)return;const version=contextVersion.value;busy.value=true;actionError.value='';try{await action();if(version!==contextVersion.value||screenAbort.signal.aborted)return;notify(success);await resource.refresh()}catch(error){if(version===contextVersion.value&&!screenAbort.signal.aborted&&!isCancelled(error))actionError.value=(error as Error).message}finally{if(version===contextVersion.value)busy.value=false}}
async function photo(file:File,campus:number){if(!file.type.startsWith('image/'))throw new Error('请选择图片文件');const body=new FormData();body.append('file',file);return api<Attachment>('/files',{method:'POST',body,campusId:campus,signal:screenAbort.signal})}
async function avatar(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0],child=family.value?.student;if(!file||!child)return;const campus=child.campusId;if(!campus){notify('孩子所属校区不可用，请刷新','error');return}await act(async()=>{const saved=await photo(file,campus);await api(`/students/${child.id}/avatar`,{method:'PUT',body:{avatarFileId:saved.id},signal:screenAbort.signal})},'孩子头像已更新');input.value=''}
async function intent(account:Family['accounts'][number],value:string|number){if(!value)return;await act(()=>api(`/accounts/${account.id}/renewal-intent`,{method:'PUT',body:{intention:value,expectedVersion:account.intentVersion}}),'续费意向已保存，负责老师和校长可查看')}
async function meal(ordered:boolean){const page=family.value;if(!page)return;await act(()=>api(`/students/${page.student.id}/meal-order`,{method:'PUT',body:{ordered,expectedVersion:page.meal?.version||0}}),ordered?'今日订餐已登记':'今日已选择不订餐')}
async function qrUpload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0],campus=Number(configCampusId.value);if(!file||!campus)return;await act(async()=>{configQr.value=await photo(file,campus)},'二维码图片已上传，请保存校区设置');input.value=''}
async function saveConfig(){await act(async()=>{const text=configPrice.value.trim();if(text&&!/^\d+(?:\.\d{1,2})?$/.test(text))throw new Error('餐费最多保留两位小数');await api(`/campuses/${configCampusId.value}/family-services`,{method:'PUT',body:{mealPrice:text?Math.round(Number(text)*100):null,paymentQrFileId:configQr.value?.id||null,expectedVersion:config.data.value?.version||0}});await config.refresh()},'校区餐费与缴费二维码已保存')}
const image=(file:Attachment)=>attachmentUrl(serviceBase,file.url)
</script>
<template>
  <PageHeader :title="isParent?'课程与今日订餐':'续费意向与订餐'" subtitle="清楚了解每一份安排，及时回应每一位家长。" />
  <section class="panel family-filter"><SoftSelect v-model="studentId" :disabled="busy" aria-label="选择孩子" :placeholder="family?.student.name||'全部授权学生'" :options="[...(!isParent?[{value:'',label:'全部授权学生'}]:[]),...(resource.data.value?.students||[]).map(s=>({value:s.id,label:`${s.name} · ${s.className}`}))]" /><button class="text-btn" :disabled="busy" @click="resource.refresh">刷新</button></section>
  <p v-if="actionError" class="family-error" role="alert">{{actionError}}</p>
  <LoadState :loading="resource.loading.value" :error="resource.error.value" @retry="resource.refresh">
    <template v-if="family"><section class="panel family-child"><StudentAvatar :student="family.student" /><div><h2>{{family.student.name}}</h2><p>{{family.student.grade}} · {{family.student.className}} · {{family.student.campusName}}</p></div><label class="btn secondary small-btn" :class="{disabled:busy}">上传头像<input type="file" accept="image/*" :disabled="busy" @change="avatar" /></label></section>
      <template v-if="isParent"><div v-if="low.length" class="family-warning"><AppIcon name="BellRing" :size="22" /><div><strong>有 {{low.length}} 门课程需要关注余额</strong><p>按各课程设置的预警线提醒，可直接选择续费意向。</p></div></div><h2 class="family-heading">课程余额</h2><div class="family-courses"><article v-for="account in family.accounts" :key="account.id" class="panel family-course"><header><h3>{{account.courseName}}</h3><span class="badge" :class="account.lowBalance?'amber':'green'">{{account.lowBalance?'余额预警':'余额充足'}}</span></header><strong class="family-balance">{{account.availableBalance??account.balance}}<small>{{account.unit}}</small></strong><p>预警线 {{account.warningThreshold}} {{account.unit}}<template v-if="account.refundReserved"> · 退款预留 {{account.refundReserved}} {{account.unit}}</template></p><label class="field"><span>续费意向</span><SoftSelect :model-value="account.intention||''" :disabled="busy" aria-label="选择续费意向" :options="[{value:'',label:'请选择续费意向'},{value:'INTERESTED',label:'有意向续费'},{value:'NOT_NOW',label:'暂不续费'}]" @change="value=>intent(account,value)" /></label></article><p v-if="!family.accounts.length" class="compact-empty">暂无课程账户，请联系校区核对报名。</p></div>
      <section class="panel family-meal"><header><div><h2>今天订餐</h2><p>{{family.date}} · {{family.settings.mealPrice==null?'校区尚未配置餐费':`餐费 ${money(family.settings.mealPrice)}`}}</p></div><AppIcon name="Utensils" :size="27" /></header><p class="family-order-status">{{family.meal?family.meal.ordered?`已订餐 · 本单 ${money(family.meal.amount)}`:'今天不订餐':'尚未选择今日用餐安排'}}</p><div class="row-actions"><button class="btn primary" :disabled="busy||family.settings.mealPrice==null||family.meal?.ordered===true" @click="meal(true)">今天订餐</button><button class="btn secondary" :disabled="busy||family.meal?.ordered===false" @click="meal(false)">今天不订餐</button></div><p class="form-hint">餐费按下单时的价格记录，订餐不扣减课程课时。</p></section>
      <section class="panel family-payment"><h2>扫码缴费</h2><template v-if="family.settings.paymentQr"><AttachmentList :files="[family.settings.paymentQr]" /><p>{{family.settings.campusName}} · 可长按二维码查看或保存</p><p>点击二维码图片查看</p><p class="form-hint">线下扫码缴费后请联系校区核对到账；扫码本身不会增加课时或标记已付款。</p></template><p v-else class="compact-empty">校区暂未设置缴费二维码，请联系老师。</p></section></template>
    </template>
    <p v-if="isParent&&!family" class="compact-empty">暂无已绑定的孩子，请联系校区核对账号绑定。</p>
    <template v-if="!isParent"><section class="panel family-staff"><h2>家长续费意向</h2><article v-for="item in resource.data.value?.intents" :key="item.id"><div><strong>{{item.studentName}} · {{item.courseName}}</strong><p>{{item.parentName}} · {{item.campusName}}</p></div><span class="badge" :class="item.intention==='INTERESTED'?'green':'amber'">{{item.intention==='INTERESTED'?'有意向续费':'暂不续费'}}</span></article><p v-if="!resource.data.value?.intents.length" class="compact-empty">当前权限范围内暂无家长续费意向。</p></section><section class="panel family-staff"><h2>{{selectedDate}} 订餐情况 · {{resource.data.value?.meals.filter(m=>m.ordered).length||0}} 份</h2><article v-for="item in resource.data.value?.meals" :key="item.id"><div><strong>{{item.studentName}} · {{item.className}}</strong><p>{{item.parentName}} · {{item.campusName}} · {{money(item.amount)}}</p></div><span class="badge" :class="item.ordered?'green':'amber'">{{item.ordered?'已订餐':'不订餐'}}</span></article><p v-if="!resource.data.value?.meals.length" class="compact-empty">当日暂无订餐选择。</p></section></template>
    <section v-if="isAdmin" class="panel family-config"><h2>校区餐费与收款码</h2><SoftSelect v-model="configCampusId" :disabled="busy" aria-label="设置哪个校区" placeholder="请选择校区" :options="configCampuses.map(c=>({value:c.id,label:c.name}))" /><LoadState :loading="config.loading.value" :error="config.error.value" @retry="config.refresh"><template v-if="config.data.value"><label class="field"><span>每份餐费（元，留空暂停订餐）</span><input v-model="configPrice" type="number" min="0" step="0.01" :disabled="busy" /></label><img v-if="configQr" :src="image(configQr)" alt="待保存的收款二维码" class="payment-qr" /><div class="row-actions"><label class="btn secondary">上传收款二维码<input type="file" accept="image/*" :disabled="busy" @change="qrUpload" /></label><button v-if="configQr" class="btn secondary" :disabled="busy" @click="configQr=null">移除二维码</button><button class="btn primary" :disabled="busy" @click="saveConfig">保存校区设置</button></div></template></LoadState></section>
  </LoadState>
</template>
<style scoped>
.family-filter,.family-child{padding:18px 22px;display:flex;align-items:center;gap:16px;margin-bottom:18px}.family-filter .soft-select{flex:1}.family-child>div{flex:1;min-width:0}.family-child h2{font-size:19px}.family-child p,.family-course p,.family-meal p,.family-payment p,.family-staff p{color:var(--text-secondary);font-size:13px;line-height:1.8}.family-child input[type=file],.family-config input[type=file]{display:none}.family-warning{display:flex;gap:14px;background:#fff4e7;color:#9a622e;border-radius:20px;padding:19px;margin-bottom:22px}.family-warning p{font-size:13px;line-height:1.8;margin-top:5px}.family-heading{font-size:19px;margin:23px 0 14px}.family-courses{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:16px}.family-course,.family-meal,.family-payment,.family-config,.family-staff{padding:22px;margin-bottom:20px}.family-course header,.family-meal header,.family-staff article{display:flex;align-items:center;justify-content:space-between;gap:14px}.family-course h3{font-size:16px}.family-balance{font-size:36px;display:block;line-height:1.8}.family-balance small{font-size:14px;font-weight:400;margin-left:7px}.family-course .field{margin-top:18px}.family-meal h2,.family-payment h2,.family-config h2,.family-staff h2{font-size:19px;margin-bottom:12px}.family-order-status{padding:12px 0}.family-payment{text-align:center}.payment-qr{display:block;width:190px;height:190px;object-fit:contain;margin:16px auto;border-radius:16px;border:1px solid var(--border);background:white}.family-payment .btn{margin-top:14px}.family-staff article{padding:17px 0;border-bottom:1px solid var(--border)}.family-staff .badge{flex-shrink:0}.family-config>.soft-select{margin:14px 0}.family-config .row-actions,.family-meal .row-actions{flex-wrap:wrap}.family-error{padding:16px;background:#fff0ef;color:#b9433b;border-radius:15px;margin-bottom:18px;overflow-wrap:anywhere}.disabled{opacity:.5}
@media(max-width:600px){.family-child{padding:18px 16px;gap:10px;flex-wrap:wrap}.family-child p{font-size:12px}.family-course,.family-meal,.family-payment,.family-staff,.family-config{padding:19px}.family-staff article{align-items:flex-start}.family-staff strong{font-size:14px}.family-staff p{font-size:12px}.family-filter{padding:15px}}
</style>
